"use client";

import React, { Suspense } from "react";
import { Navbar } from "@/components/Navbar";
import { Hero } from "@/components/Hero";
import {
    ProblemsSkeleton,
    SolutionsSkeleton,
    DashboardSkeleton,
    MethodologySkeleton,
    ReviewsSkeleton,
    FAQSkeleton,
    FooterSkeleton
} from "@/components/PageSkeletons";

// Lazy load below-the-fold components
// explicit named export handling for React.lazy
const Problems = React.lazy(() => import("@/components/Problems").then(module => ({ default: module.Problems })));
const Solutions = React.lazy(() => import("@/components/Solutions").then(module => ({ default: module.Solutions })));
const Dashboard = React.lazy(() => import("@/components/Dashboard").then(module => ({ default: module.Dashboard })));
const Methodology = React.lazy(() => import("@/components/Methodology").then(module => ({ default: module.Methodology })));
const Reviews = React.lazy(() => import("@/components/Reviews").then(module => ({ default: module.Reviews })));
const FAQ = React.lazy(() => import("@/components/FAQ").then(module => ({ default: module.FAQ })));
const Footer = React.lazy(() => import("@/components/Footer").then(module => ({ default: module.Footer })));

export default function Home() {
    return (
        <main className="min-h-screen bg-background relative selection:bg-brand/30 selection:text-white overflow-x-hidden">
            {/* Texture Overlay */}
            <div className="fixed inset-0 bg-noise z-50 pointer-events-none opacity-20" />

            <Navbar />

            <Hero />

            <Suspense fallback={<ProblemsSkeleton />}>
                <Problems />
            </Suspense>

            <Suspense fallback={<SolutionsSkeleton />}>
                <Solutions />
            </Suspense>

            <Suspense fallback={<DashboardSkeleton />}>
                <Dashboard />
            </Suspense>

            <Suspense fallback={<MethodologySkeleton />}>
                <Methodology />
            </Suspense>

            <Suspense fallback={<ReviewsSkeleton />}>
                <Reviews />
            </Suspense>

            <Suspense fallback={<FAQSkeleton />}>
                <FAQ />
            </Suspense>

            <Suspense fallback={<FooterSkeleton />}>
                <Footer />
            </Suspense>
        </main>
    );
}
